add_filter( 'rest_authentication_errors', 'perfectpixel_disable_rest_api_guests', 99 );

function perfectpixel_disable_rest_api_guests( $result ) {
	if ( ! empty( $result ) || is_user_logged_in() ) {
		return $result;
	}
	$route = '';
	if ( isset( $GLOBALS['wp']->query_vars['rest_route'] ) ) {
		$route = $GLOBALS['wp']->query_vars['rest_route'];
	} elseif ( isset( $_GET['rest_route'] ) ) {
		$route = sanitize_text_field( wp_unslash( $_GET['rest_route'] ) );
	}
	$route = ltrim( (string) $route, '/' );
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{rest_public_namespaces}}' ) ) ) as $namespace ) {
		if ( 0 === strpos( $route, trim( $namespace, '/' ) ) ) {
			return $result;
		}
	}
	return new WP_Error( 'rest_login_required', __( 'Sorry, you are not allowed to do that.' ), array( 'status' => 401 ) );
}
